  updateCrew(dt, p) {
    this.crewStates = this.crewStates || new Map();
    if (this.crewPropId !== p.id) {
      this.crewPropId = p.id;
      this.crewStates.clear();
      this.hiddenPlants.clear();
      this.trimGhosts.clear();
